// LinkedIn Sales Navigator Scraper using Puppeteer
// IMPORTANT: This requires Puppeteer to be installed in your n8n instance
// For n8n cloud: Use Execute Command node with npm install puppeteer first
// For self-hosted: Install via: npm install puppeteer

const puppeteer = require('puppeteer');

async function scrapeLinkedIn(linkedinCookie) {
  const browser = await puppeteer.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-accelerated-2d-canvas',
      '--disable-gpu'
    ]
  });

  const page = await browser.newPage();

  // Set user agent to avoid detection
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');

  // Set LinkedIn authentication cookie
  await page.setCookie({
    name: 'li_at',
    value: linkedinCookie,
    domain: '.linkedin.com',
    path: '/',
    httpOnly: true,
    secure: true
  });

  // LinkedIn Sales Navigator search URL (customize your search)
  // Target: Founders/CEOs in SaaS/E-commerce companies, 10-500 employees
  const searchURL = 'https://www.linkedin.com/search/results/people/?keywords=founder%20OR%20ceo%20OR%20operations%20manager&origin=GLOBAL_SEARCH_HEADER';

  await page.goto(searchURL, { 
    waitUntil: 'networkidle2',
    timeout: 30000 
  });

  // Random delay (anti-detection)
  await new Promise(resolve => setTimeout(resolve, 2000 + Math.random() * 3000));

  // Wait for search results to load
  try {
    await page.waitForSelector('.reusable-search__result-container', { timeout: 10000 });
  } catch (error) {
    console.log('LinkedIn search results not loaded:', error.message);
    await browser.close();
    return [];
  }

  // Extract lead data
  const leads = await page.evaluate(() => {
    const results = [];
    const items = document.querySelectorAll('.reusable-search__result-container');

    items.forEach((item, index) => {
      if (index >= 50) return; // Limit to 50 results per session

      try {
        const nameElement = item.querySelector('.entity-result__title-text a span[aria-hidden="true"]');
        const titleElement = item.querySelector('.entity-result__primary-subtitle');
        const companyElement = item.querySelector('.entity-result__secondary-subtitle');
        const profileLinkElement = item.querySelector('.entity-result__title-text a');
        const locationElement = item.querySelector('.entity-result__secondary-subtitle + div');

        const name = nameElement?.innerText?.trim() || '';
        const title = titleElement?.innerText?.trim() || '';
        const company = companyElement?.innerText?.trim() || '';
        const profileURL = profileLinkElement?.href || '';
        const location = locationElement?.innerText?.trim() || '';

        if (name && profileURL) {
          results.push({
            full_name: name,
            job_title: title,
            company_name: company,
            linkedin_url: profileURL,
            location: location,
            source_platform: 'LinkedIn'
          });
        }
      } catch (err) {
        console.log('Error extracting item:', err);
      }
    });

    return results;
  });

  await browser.close();
  return leads;
}

// Execute scraping
const linkedinCookie = $input.first().json.linkedin_cookie;

if (!linkedinCookie || linkedinCookie === 'YOUR_LINKEDIN_COOKIE_li_at') {
  throw new Error('LinkedIn cookie (li_at) not configured. Get it from your browser cookies after logging into LinkedIn.');
}

const leads = await scrapeLinkedIn(linkedinCookie);

if (leads.length === 0) {
  return [{ json: { error: 'No leads found. Check your LinkedIn session cookie or search criteria.' } }];
}

return leads.map(lead => ({ json: lead }));

// Google Maps Local Business Scraper using Puppeteer
// Targets local businesses for B2B outreach

const puppeteer = require('puppeteer');

async function scrapeGoogleMaps(searchQuery = 'SaaS companies near me') {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const page = await browser.newPage();
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36');

  // Navigate to Google Maps search
  const encodedQuery = encodeURIComponent(searchQuery);
  await page.goto(`https://www.google.com/maps/search/${encodedQuery}`, {
    waitUntil: 'networkidle2',
    timeout: 30000
  });

  // Random delay
  await new Promise(resolve => setTimeout(resolve, 3000 + Math.random() * 2000));

  // Scroll to load more results
  await page.evaluate(() => {
    const scrollableDiv = document.querySelector('[role="feed"]');
    if (scrollableDiv) {
      scrollableDiv.scrollBy(0, 2000);
    }
  });

  await new Promise(resolve => setTimeout(resolve, 2000));

  // Extract business data
  const leads = await page.evaluate(() => {
    const results = [];
    const items = document.querySelectorAll('[role="article"]');

    items.forEach((item, index) => {
      if (index >= 50) return;

      try {
        const nameElement = item.querySelector('[aria-label]');
        const name = nameElement?.getAttribute('aria-label') || '';

        // Extract address, phone, website from aria-label or nested elements
        const detailsText = item.innerText || '';
        const lines = detailsText.split('\n').filter(l => l.trim());

        const address = lines.find(l => l.match(/\d+.*(?:St|Ave|Rd|Blvd|Dr|Way|Street|Avenue|Road|Boulevard|Drive)/i)) || '';
        const phone = lines.find(l => l.match(/\(\d{3}\)\s?\d{3}-\d{4}/)) || '';
        const website = lines.find(l => l.match(/https?:\/\//)) || '';
        const rating = lines.find(l => l.match(/^\d\.\d/)) || '';

        if (name) {
          results.push({
            company_name: name,
            location: address,
            phone_number: phone,
            company_website: website,
            rating: rating,
            source_platform: 'Google Maps'
          });
        }
      } catch (err) {
        console.log('Error extracting item:', err);
      }
    });

    return results;
  });

  await browser.close();
  return leads;
}

// Execute scraping
const leads = await scrapeGoogleMaps('digital marketing agencies near San Francisco');

if (leads.length === 0) {
  return [{ json: { error: 'No leads found from Google Maps' } }];
}

return leads.map(lead => ({ json: lead }));

