// Clean, format, and deduplicate lead data
// Normalizes data from different platforms into standard format

const leads = [];
const seenEmails = new Set();
const seenLinkedInURLs = new Set();
const seenCompanies = new Set();

// Process all input items
$input.all().forEach((item, index) => {
  const data = item.json;

  // Skip error objects
  if (data.error) {
    console.log('Skipping error item:', data.error);
    return;
  }

  // Extract and normalize fields
  let firstName = '';
  let lastName = '';
  let fullName = data.full_name || data.name || '';

  // Split full name into first/last if needed
  if (fullName && !data.first_name) {
    const nameParts = fullName.trim().split(/\s+/);
    firstName = nameParts[0] || '';
    lastName = nameParts.slice(1).join(' ') || '';
  } else {
    firstName = data.first_name || '';
    lastName = data.last_name || '';
    fullName = `${firstName} ${lastName}`.trim();
  }

  const companyName = data.company_name || data.organization?.name || '';
  const email = data.email_address || data.email || '';
  const linkedInURL = data.linkedin_url || '';
  const sourcePlatform = data.source_platform || 'Unknown';

  // Deduplication logic
  const companyKey = companyName.toLowerCase().trim();

  // Skip if duplicate email
  if (email && seenEmails.has(email)) {
    console.log(`Duplicate email skipped: ${email}`);
    return;
  }

  // Skip if duplicate LinkedIn URL
  if (linkedInURL && seenLinkedInURLs.has(linkedInURL)) {
    console.log(`Duplicate LinkedIn URL skipped: ${linkedInURL}`);
    return;
  }

  // Skip if duplicate company + name (likely same person)
  const personKey = `${companyKey}|${fullName.toLowerCase()}`;
  if (seenCompanies.has(personKey)) {
    console.log(`Duplicate person skipped: ${fullName} at ${companyName}`);
    return;
  }

  // Mark as seen
  if (email) seenEmails.add(email);
  if (linkedInURL) seenLinkedInURLs.add(linkedInURL);
  if (companyName && fullName) seenCompanies.add(personKey);

  // Build standardized lead object
  const lead = {
    lead_id: `LEAD-${new Date().getFullYear()}-${String(leads.length + 1).padStart(4, '0')}`,
    first_name: firstName,
    last_name: lastName,
    full_name: fullName,
    company_name: companyName,
    job_title: data.job_title || data.title || '',
    industry: data.industry || 'Unknown',
    location: data.location || `${data.city || ''}, ${data.state || ''}`.replace(', ,', ''),
    source_platform: sourcePlatform,
    scrape_date: new Date().toISOString().split('T')[0],
    email_address: email,
    email_status: email ? 'Valid' : 'Not Found',
    phone_number: data.phone_number || data.phone_numbers?.[0] || '',
    linkedin_url: linkedInURL,
    company_website: data.company_website || data.organization?.website_url || data.website || '',
    company_size: data.company_size || data.organization?.estimated_num_employees || null,
    lead_score: null,
    qualification_status: 'Pending',
    qualification_notes: '',
    email_subject: '',
    email_body: '',
    email_campaign_status: 'Draft',
    pain_points: data.pain_points || '',
    recent_activity: data.recent_activity || ''
  };

  // Data quality check: require minimum fields
  if (!lead.full_name || !lead.company_name) {
    console.log('Skipping lead with missing required fields:', lead);
    return;
  }

  leads.push(lead);
});

console.log(`Processed ${$input.all().length} items, kept ${leads.length} unique leads`);

if (leads.length === 0) {
  return [{ json: { error: 'No valid leads after deduplication. All items were duplicates or incomplete.' } }];
}

return leads.map(lead => ({ json: lead }));
